export const styles=":root{color-scheme:light;--teal:#116a71;--ink:#172f33;--muted:#586a6c;--line:#d6e3e3;--paper:#f4f8f8}*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,sans-serif;color:var(--ink);background:var(--paper)}a{color:var(--teal);text-underline-offset:4px}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}:focus-visible{outline:3px solid #9c6023;outline-offset:3px}header{display:flex;align-items:center;gap:24px;padding:12px 28px;border-bottom:1px solid var(--line);background:white}header>a:last-child{margin-left:auto}.brand{display:flex;align-items:center;gap:18px;text-decoration:none}.brand img{object-fit:contain}.brand span,.badge{font-size:11px;letter-spacing:.12em}.badge{background:#e3f3f2;padding:6px 10px;border-radius:4px}.app-layout{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:calc(100vh - 87px)}aside{padding:24px 16px;background:white;border-right:1px solid var(--line)}nav{display:grid;gap:4px}nav a{padding:10px 12px;color:var(--ink);text-decoration:none;border-radius:5px}nav a[aria-current=page]{color:var(--teal);font-weight:650;background:#e5f1f1}main{padding:32px clamp(20px,3vw,48px);max-width:1500px;width:100%;min-width:0}h1{font-size:30px;line-height:1.2;margin:0 0 10px;letter-spacing:-.03em}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px}.quiet{color:var(--muted);font-size:13px}.topline{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:24px}.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}button{border:1px solid #a9bfbf;background:white;border-radius:5px;padding:10px 14px;min-height:44px;color:var(--ink);cursor:pointer}button.primary{background:var(--teal);border-color:var(--teal);color:white}button:hover{filter:brightness(.95)}button:disabled{opacity:.55;cursor:default}input,select,textarea{width:100%;border:1px solid #a9bfbf;border-radius:4px;background:white;color:var(--ink);min-height:44px;padding:9px 10px}input[type=checkbox]{width:20px;min-height:20px}select[multiple]{min-height:150px}textarea{min-height:120px;resize:vertical}.filter{max-width:420px;margin-bottom:18px}.panel{padding:24px;background:white;border:1px solid var(--line);border-radius:8px;margin-bottom:20px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.metric{padding:20px;background:white;border:1px solid var(--line);border-radius:8px}.metric strong{display:block;font-size:30px}.metric span{color:var(--muted)}.table-wrap{overflow:auto;background:white;border:1px solid var(--line);border-radius:8px}table{border-collapse:collapse;width:100%;text-align:left;font-size:14px}th,td{padding:14px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#edf5f5;font-size:12px;text-transform:uppercase;letter-spacing:.05em}td:first-child{min-width:170px}td button{padding:6px 10px;min-height:38px}tr:last-child td{border-bottom:0}.tag{display:inline-block;font-size:11px;background:#e9eff0;border-radius:3px;padding:3px 6px;margin:3px}.tag.warn{background:#fff0d5;color:#6c4210}.empty{padding:30px;color:var(--muted)}.notice{position:fixed;right:20px;bottom:20px;margin:0;max-width:calc(100vw - 40px);background:#14373b;color:white;border-radius:6px;padding:0}.notice:not(:empty){padding:12px 18px}dialog{border:1px solid var(--line);border-radius:10px;padding:26px;width:min(760px,calc(100vw - 30px));max-height:90vh;overflow:auto;color:var(--ink)}dialog::backdrop{background:#092d3580}.dialog-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.fields label{display:grid;gap:6px;font-size:13px;font-weight:600}.fields label.wide{grid-column:1/-1}.fields small{font-size:11px;font-weight:400;color:var(--muted)}#form-error{color:#9a2121}.skip{position:absolute;left:-1000px}.skip:focus{left:10px;top:10px;z-index:3;background:white;padding:10px}.timeline{padding-left:24px}.timeline li{margin-bottom:10px}.portal-view{max-width:900px;margin:auto}.portal-view h1{font-family:Georgia,serif}dl{display:grid;grid-template-columns:160px 1fr;gap:12px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}code{overflow-wrap:anywhere}.cols{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.app-layout{grid-template-columns:190px 1fr}main{padding:24px 20px}.cols{grid-template-columns:1fr}}@media(max-width:650px){header{padding:12px 16px;gap:10px}.brand img{width:105px;height:46px}.brand span{display:none}.badge{font-size:9px;letter-spacing:.04em}header>a:last-child{font-size:12px}.app-layout{display:block}aside{padding:10px;border-right:0;border-bottom:1px solid var(--line)}nav{display:flex;gap:5px;overflow:auto}nav a{white-space:nowrap;padding:10px}aside>.quiet{display:none}main{padding:24px 16px}.fields{grid-template-columns:1fr}.fields label.wide{grid-column:auto}.metrics{gap:10px}.metric{padding:14px}h1{font-size:26px}.panel{padding:18px}dl{grid-template-columns:1fr;gap:4px}dd{margin-bottom:10px}}\n\n.filterbar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.filterbar .filter{margin:0;flex:2;min-width:200px}.filterbar select{width:auto;flex:1;min-width:150px}.service-picker{border:1px solid var(--line);border-radius:6px;padding:12px;max-height:260px;overflow:auto}.fields .pick-option{display:flex;align-items:flex-start;gap:10px;font-weight:400;padding:10px;border-bottom:1px solid var(--line)}.pick-option input{flex:none}.pick-option span{overflow-wrap:anywhere}dd{white-space:pre-wrap}#record-view{width:min(1000px,calc(100vw - 30px))}#record-view dd{max-height:400px;overflow:auto}input:disabled,textarea:disabled{background:#f2f5f5;color:#586a6c}.table-wrap .actions{min-width:190px}button{font-size:13px}\n.fields fieldset{min-width:0;border:0;padding:0;margin:0}.fields fieldset legend{font-size:13px;font-weight:600;margin-bottom:6px}.fields fieldset.wide{grid-column:1/-1}\n";
